#include<bits/stdc++.h>
using namespace std;
int main(){
    int t;
    ios_base::sync_with_stdio(false);cout.tie(nullptr);cin.tie(nullptr);
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        int p[n+1];
        for(int i=1;i<=n;i++){
            cin>>p[i];
        }
        bool us[n+1];
        memset(us,0,sizeof us);
        int re=0;
        for(int i=1;i<=n;i++){
            if(!us[i]){
                int cu=i;
                int le=0;
                while(us[cu]==0){
                    le++;
                    us[cu]=1;
                    cu=p[cu];
                }
                re+=(le-1)/2;
            }
        }
        cout<<re<<'\n';
    }
}
